def check_equation(a, b, c):
    """Checks if the triple (a, b, c) satisfies the equation."""
    # a^3 (b^3 + c^3) = 2012 (abc + 2)
    lhs = a**3 * (b**3 + c**3)
    rhs = 2012 * (a * b * c + 2)
    return lhs == rhs

found_solutions = []
limit = 10 # Testing a small range to look for counterexamples

# Iterate over triples such that 1 <= a <= b <= c <= limit
for a in range(1, limit + 1):
    for b in range(a, limit + 1):
        for c in range(b, limit + 1):
            if check_equation(a, b, c):
                found_solutions.append((a, b, c))

print(f"Solutions found in range a, b, c <= {limit}: {found_solutions}")
